# M remains 111...1
M = int('1' * 1000)

def calculate_A(M, N):
    if N == 0:
        return None

    Q = M // N
    Q_str = str(Q)

    A = Q_str.count('0')
    return A, Q_str

# Test N=9 and N=10
N_values = [9, 10]
results = {}

for N in N_values:
    A, Q_str = calculate_A(M, N)
    results[N] = {'A': A, 'Q': Q_str}

print("--- Second Round Test Results ---")
for N, data in results.items():
    print(f"N={N}: A={data['A']}, Q length={len(data['Q'])}")
    snippet = data['Q'][:15] + '...' + data['Q'][-15:]
    print(f"  Q snippet: {snippet}")
